  ["Fisika||Usaha dan Energi||Energi Kinetik dan Potensial"]: [
    {"question":"Sebuah benda bermassa 2 kg bergerak dengan kecepatan 3 m/s. Besar energi kinetik benda adalah...","options":["4,5 J","9 J","18 J","36 J"],"correctIndex":1,"difficulty":"easy","explanation":"Energi kinetik dihitung dengan rumus EK = ½mv² = ½ × 2 × 3² = 9 J."},
    {"question":"Sebuah buku bermassa 0,5 kg berada di atas meja setinggi 1,2 m dari lantai. Jika g = 10 m/s², energi potensial buku terhadap lantai adalah...","options":["0,6 J","6 J","12 J","60 J"],"correctIndex":1,"difficulty":"easy","explanation":"Energi potensial gravitasi dihitung dengan rumus EP = mgh = 0,5 × 10 × 1,2 = 6 J."},
    {"question":"Buah kelapa bermassa 2 kg jatuh bebas dari ketinggian 5 m. Jika g = 10 m/s², kecepatan buah tepat sebelum menyentuh tanah berdasarkan hukum kekekalan energi mekanik adalah...","options":["5 m/s","10 m/s","20 m/s","50 m/s"],"correctIndex":1,"difficulty":"medium","explanation":"Energi mekanik kekal: mgh = ½mv², sehingga v = √(2gh) = √(2 × 10 × 5) = 10 m/s."},
    {"question":"Roller coaster bermassa 500 kg bergerak dari titik setinggi 20 m dengan kecepatan awal nol. Jika g = 10 m/s², energi kinetik roller coaster saat berada di titik setinggi 10 m adalah...","options":["50.000 J","100.000 J","150.000 J","200.000 J"],"correctIndex":0,"difficulty":"medium","explanation":"Energi mekanik di puncak = mgh = 500 × 10 × 20 = 100.000 J. Pada ketinggian 10 m, EP = 500 × 10 × 10 = 50.000 J, sehingga EK = 100.000 − 50.000 = 50.000 J."},
    {"question":"Benda bermassa 1 kg dilempar vertikal ke atas dengan kecepatan awal 20 m/s. Jika g = 10 m/s², kecepatan benda saat berada pada ketinggian 10 m adalah...","options":["10 m/s","14,1 m/s","17,3 m/s","20 m/s"],"correctIndex":1,"difficulty":"hard","explanation":"Energi mekanik awal = ½mv² = ½ × 1 × 20² = 200 J. Pada ketinggian 10 m, EP = mgh = 1 × 10 × 10 = 100 J, sehingga EK = 200 − 100 = 100 J. Maka v = √(2 × EK / m) = √(2 × 100 / 1) ≈ 14,1 m/s."},
  ],

