  ["Matematika||Geometri||Segitiga dan Segiempat"]: [
    {"question":"Sebuah segitiga siku-siku memiliki alas 8 cm dan tinggi 6 cm. Berapakah luas segitiga tersebut?","options":["48 cm²","24 cm²","14 cm²","20 cm²"],"correctIndex":1,"difficulty":"easy","explanation":"Luas segitiga = ½ × alas × tinggi = ½ × 8 × 6 = 24 cm²."},
    {"question":"Sebuah persegi memiliki panjang sisi 7 cm. Berapakah keliling persegi tersebut?","options":["14 cm","28 cm","49 cm","56 cm"],"correctIndex":1,"difficulty":"easy","explanation":"Keliling persegi = 4 × sisi = 4 × 7 = 28 cm."},
    {"question":"Sebuah jajargenjang memiliki alas 12 cm, tinggi 8 cm, dan sisi miring 10 cm. Berapakah keliling jajargenjang tersebut?","options":["40 cm","44 cm","56 cm","96 cm"],"correctIndex":1,"difficulty":"medium","explanation":"Keliling jajargenjang = 2 × (alas + sisi miring) = 2 × (12 + 10) = 44 cm. Tinggi 8 cm hanya digunakan untuk luas, bukan keliling."},
    {"question":"Keliling sebuah persegi panjang adalah 50 cm. Jika lebarnya 10 cm, berapakah panjang persegi panjang tersebut?","options":["15 cm","20 cm","25 cm","30 cm"],"correctIndex":0,"difficulty":"medium","explanation":"Keliling persegi panjang = 2 × (panjang + lebar). Maka 50 = 2 × (p + 10), sehingga p + 10 = 25 dan p = 15 cm."},
    {"question":"Keliling sebuah persegi sama dengan keliling persegi panjang yang berukuran 12 cm × 6 cm. Berapakah luas persegi tersebut?","options":["36 cm²","64 cm²","81 cm²","144 cm²"],"correctIndex":2,"difficulty":"hard","explanation":"Keliling persegi panjang = 2 × (12 + 6) = 36 cm. Sisi persegi = 36 ÷ 4 = 9 cm, sehingga luas persegi = 9 × 9 = 81 cm²."},
  ],

